package com.primehr.evidence.application;

import com.fasterxml.jackson.databind.ObjectMapper;import com.primehr.config.PrimeHrProperties;import com.primehr.evidence.api.EvidenceAssessmentDtos.*;import com.primehr.evidence.api.EvidenceFrameworkDtos.FrameworkResponse;import com.primehr.evidence.domain.*;import com.primehr.evidence.infrastructure.*;import com.primehr.integration.administrative.*;import com.primehr.integration.humanresource.*;import com.primehr.notification.application.NotificationProjectionService;import com.primehr.notification.domain.PrimeHrNotification.SourceDomain;import com.primehr.rsp.applicant.storage.DocumentStorage;import com.primehr.shared.audit.PrimeHrAuditService;import com.primehr.shared.exception.*;import org.springframework.security.access.AccessDeniedException;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.multipart.MultipartFile;import java.io.*;import java.nio.charset.StandardCharsets;import java.security.*;import java.time.*;import java.util.*;import java.util.function.Function;import java.util.stream.Collectors;

@Service@Transactional public class EvidenceAssessmentServiceImpl implements EvidenceAssessmentService{
 private static final ZoneId MANILA=ZoneId.of("Asia/Manila");private final EvidenceAssessmentCycleRepository cycles;private final EvidenceAssessmentCaseRepository cases;private final EvidenceArtifactRepository artifacts;private final EvidenceFindingRepository findings;private final EvidenceGapRepository gaps;private final EvidenceCorrectiveActionRepository actions;private final EvidenceAssessmentEventRepository events;private final EvidenceRequirementRepository requirements;private final EvidenceFrameworkService frameworks;private final HumanResourceEmployeeDirectoryClient directory;private final HumanResourceAssessmentSubjectClient hr;private final AdministrativePerformancePlanningClient administrative;private final EvidenceLiveSourceVerifier sourceVerifier;private final DocumentStorage storage;private final PrimeHrProperties properties;private final PrimeHrAuditService audit;private final ObjectMapper json;private final NotificationProjectionService notifications;
 public EvidenceAssessmentServiceImpl(EvidenceAssessmentCycleRepository cy,EvidenceAssessmentCaseRepository ca,EvidenceArtifactRepository ar,EvidenceFindingRepository f,EvidenceGapRepository g,EvidenceCorrectiveActionRepository ac,EvidenceAssessmentEventRepository ev,EvidenceRequirementRepository req,EvidenceFrameworkService fw,HumanResourceEmployeeDirectoryClient d,HumanResourceAssessmentSubjectClient h,AdministrativePerformancePlanningClient ad,EvidenceLiveSourceVerifier sv,DocumentStorage st,PrimeHrProperties p,PrimeHrAuditService au,ObjectMapper j,NotificationProjectionService n){cycles=cy;cases=ca;artifacts=ar;findings=f;gaps=g;actions=ac;events=ev;requirements=req;frameworks=fw;directory=d;hr=h;administrative=ad;sourceVerifier=sv;storage=st;properties=p;audit=au;json=j;notifications=n;}

 @Override@Transactional(readOnly=true)public List<CycleResponse>cycles(String a){return cycles.findByAgencyIdOrderByPeriodStartDesc(a).stream().map(this::cycleResponse).toList();}@Override@Transactional(readOnly=true)public CycleResponse cycle(String a,String id){return cycleResponse(cycleEntity(a,id));}
 @Override public CycleResponse createCycle(String a,CycleInput in,String c){if(in.recordVersion()!=null)throw new IllegalArgumentException("recordVersion must be omitted for a new cycle");String code=norm(in.code());if(cycles.existsByAgencyIdAndNormalizedCode(a,code))throw new OptimisticConflictException("Assessment cycle code already exists");FrameworkResponse fw=frameworks.get(a,in.frameworkVersionId());published(fw);var value=cycles.saveAndFlush(new EvidenceAssessmentCycle(a,in.code(),in.title(),in.description(),fw.id(),fw.definitionVersion(),fw.contentRevision(),shaObject(fw),in.periodStart(),in.periodEnd(),in.dueDate()));var out=cycleResponse(value);record(a,"CREATE_EVIDENCE_ASSESSMENT_CYCLE","EVIDENCE_ASSESSMENT_CYCLE",value,null,out,null,c);return out;}
 @Override public CycleResponse updateCycle(String a,String id,CycleInput in,String c){var value=cycleEntity(a,id);check(value.getVersion(),in.recordVersion());if(!value.getCode().equalsIgnoreCase(in.code())||!value.getFrameworkVersionId().equals(in.frameworkVersionId()))throw new IllegalArgumentException("Cycle code and framework version cannot change");var before=cycleResponse(value);value.update(in.title(),in.description(),in.periodStart(),in.periodEnd(),in.dueDate());value=cycles.saveAndFlush(value);var out=cycleResponse(value);record(a,"UPDATE_EVIDENCE_ASSESSMENT_CYCLE","EVIDENCE_ASSESSMENT_CYCLE",value,before,out,null,c);return out;}
 @Override public CycleResponse transitionCycle(String a,String id,Transition in,String action,String c){var value=cycleEntity(a,id);check(value.getVersion(),in.recordVersion());var before=cycleResponse(value);if("open".equals(action)){FrameworkResponse fw=frameworks.get(a,value.getFrameworkVersionId());published(fw);if(!shaObject(fw).equals(value.getFrameworkFingerprint()))throw new OptimisticConflictException("Published framework content changed; create another assessment cycle");value.open(audit.currentActor(),in.reason(),Instant.now());}else if("close".equals(action)){if(cases.findByAgencyIdAndCycleIdOrderByCreatedAtDesc(a,id).stream().anyMatch(x->x.getStatus()!=EvidenceAssessmentCase.Status.FINALIZED&&x.getStatus()!=EvidenceAssessmentCase.Status.WITHDRAWN))throw new IllegalStateException("All assessment cases must be finalized or withdrawn before closing the cycle");value.close(audit.currentActor(),in.reason(),Instant.now());}else if("cancel".equals(action))value.cancel(audit.currentActor(),in.reason(),Instant.now());else throw new IllegalArgumentException("Unsupported cycle action");value=cycles.saveAndFlush(value);var out=cycleResponse(value);record(a,"EVIDENCE_CYCLE_"+action.toUpperCase(Locale.ROOT),"EVIDENCE_ASSESSMENT_CYCLE",value,before,out,in.reason(),c);return out;}

 @Override@Transactional(readOnly=true)public List<CaseResponse>cases(String a,String actor,PermissionDataScope scope){return cases.findByAgencyIdOrderByCreatedAtDesc(a).stream().filter(x->visible(a,x,actor,scope)).map(x->caseResponse(a,x,actor,scope)).toList();}@Override@Transactional(readOnly=true)public CaseResponse get(String a,String id,String actor,PermissionDataScope scope){var value=caseEntity(a,id);access(a,value,actor,scope);return caseResponse(a,value,actor,scope);}
 @Override public CaseResponse createCase(String a,CaseInput in,String token,String actor,PermissionDataScope scope,String c){if(in.recordVersion()!=null)throw new IllegalArgumentException("recordVersion must be omitted for a new case");var cycle=cycleEntity(a,in.cycleId());if(cycle.getStatus()!=EvidenceAssessmentCycle.Status.OPEN)throw new IllegalStateException("Assessment cycle must be open");if(cases.existsByAgencyIdAndCycleIdAndNormalizedCode(a,cycle.getId(),norm(in.code())))throw new OptimisticConflictException("Assessment case code already exists in the cycle");var owner=person(in.ownerEmployeeNo(),token);var validator=person(in.validatorEmployeeNo(),token);if(scope!=PermissionDataScope.AGENCY_WIDE&&!owner.employeeNo().equalsIgnoreCase(actor))throw new AccessDeniedException("Assigned scope may create only a case owned by the authenticated employee");var org=organization(in.organizationType(),in.organizationId(),token);var value=cases.saveAndFlush(new EvidenceAssessmentCase(a,cycle.getId(),cycle.getFrameworkVersionId(),in.code(),in.title(),org.type(),org.id(),org.name(),org.sourceFingerprint(),owner,validator));event(a,value,"CASE",value.getId(),"CREATE",actor,null,null,value.getStatus().name());var out=caseResponse(a,value,actor,scope);record(a,"CREATE_EVIDENCE_ASSESSMENT_CASE","EVIDENCE_ASSESSMENT_CASE",value,null,out,null,c);return out;}
 @Override public CaseResponse updateCase(String a,String id,CaseInput in,String token,String actor,PermissionDataScope scope,String c){var value=caseEntity(a,id);ownerMutation(a,value,actor,scope);check(value.getVersion(),in.recordVersion());if(!value.getCycleId().equals(in.cycleId())||!value.getCode().equalsIgnoreCase(in.code()))throw new IllegalArgumentException("Cycle and case code cannot change");var org=organization(in.organizationType(),in.organizationId(),token);var before=caseResponse(a,value,actor,scope);value.update(in.title(),org.type(),org.id(),org.name(),org.sourceFingerprint());value=cases.saveAndFlush(value);event(a,value,"CASE",value.getId(),"UPDATE",actor,null,value.getStatus().name(),value.getStatus().name());var out=caseResponse(a,value,actor,scope);record(a,"UPDATE_EVIDENCE_ASSESSMENT_CASE","EVIDENCE_ASSESSMENT_CASE",value,before,out,null,c);return out;}
 @Override public CaseResponse submit(String a,String id,Transition in,String actor,PermissionDataScope scope,String c){var value=caseEntity(a,id);ownerMutation(a,value,actor,scope);check(value.getVersion(),in.recordVersion());String from=value.getStatus().name();ensureCurrentEvidenceHealthy(a,value);value.submit(actor,Instant.now());value=cases.saveAndFlush(value);event(a,value,"CASE",id,"SUBMIT",actor,in.reason(),from,value.getStatus().name());var out=caseResponse(a,value,actor,scope);record(a,"SUBMIT_EVIDENCE_ASSESSMENT_CASE","EVIDENCE_ASSESSMENT_CASE",value,null,out,in.reason(),c);notifications.replaceAssignment(caseProjection(a,value.getValidatorEmployeeNo(),value),c);return out;}
 @Override public CaseResponse withdraw(String a,String id,Transition in,String actor,PermissionDataScope scope,String c){var value=caseEntity(a,id);ownerMutation(a,value,actor,scope);check(value.getVersion(),in.recordVersion());String from=value.getStatus().name();value.withdraw(actor,in.reason(),Instant.now());value=cases.saveAndFlush(value);event(a,value,"CASE",id,"WITHDRAW",actor,in.reason(),from,value.getStatus().name());notifications.close(caseProjection(a,value.getOwnerEmployeeNo(),value),c);return auditedCase(a,value,actor,scope,"WITHDRAW_EVIDENCE_ASSESSMENT_CASE",in.reason(),c);}
 @Override public CaseResponse recuse(String a,String id,Transition in,String actor,PermissionDataScope scope,String c){var value=caseEntity(a,id);access(a,value,actor,scope);check(value.getVersion(),in.recordVersion());String from=value.getStatus().name();value.recuse(actor,in.reason());value=cases.saveAndFlush(value);event(a,value,"CASE",id,"VALIDATOR_RECUSE",actor,in.reason(),from,from);notifications.close(caseProjection(a,actor,value),c);return auditedCase(a,value,actor,scope,"RECUSE_EVIDENCE_VALIDATOR",in.reason(),c);}
 @Override public CaseResponse reassign(String a,String id,ReassignValidator in,String token,String actor,PermissionDataScope scope,String c){if(scope!=PermissionDataScope.AGENCY_WIDE)throw new AccessDeniedException("Validator reassignment requires Agency Wide scope");var value=caseEntity(a,id);check(value.getVersion(),in.recordVersion());String prior=value.getValidatorEmployeeNo();value.reassignValidator(person(in.validatorEmployeeNo(),token));value=cases.saveAndFlush(value);event(a,value,"CASE",id,"REASSIGN_VALIDATOR",actor,in.reason(),prior,value.getValidatorEmployeeNo());if(value.getStatus()==EvidenceAssessmentCase.Status.SUBMITTED||value.getStatus()==EvidenceAssessmentCase.Status.RESUBMITTED)notifications.replaceAssignment(caseProjection(a,value.getValidatorEmployeeNo(),value),c);return auditedCase(a,value,actor,scope,"REASSIGN_EVIDENCE_VALIDATOR",in.reason(),c);}

 @Override public ArtifactResponse addLiveSource(String a,String id,LiveSourceInput in,String token,String actor,PermissionDataScope scope,String c){var value=caseEntity(a,id);ownerMutation(a,value,actor,scope);check(value.getVersion(),in.metadata().caseRecordVersion());var req=requirement(a,value,in.metadata().requirementId());var verified=sourceVerifier.verify(a,new EvidenceLiveSourceVerifier.Request(in.sourceType(),in.sourceId(),in.sourceVersion(),in.sourceFingerprint(),in.sourceChangedAt()),token,actor,c);EvidenceArtifact prior=superseded(a,value,req,in.metadata().supersedesId());var row=EvidenceArtifact.live(a,id,req.getId(),req.getCode(),in.metadata().title(),in.metadata().notes(),verified.type(),verified.sourceId(),verified.sourceVersion(),verified.sourceFingerprint(),verified.sourceLabel(),verified.sourceChangedAt(),in.metadata().classification(),in.metadata().visibility(),in.metadata().retentionTag(),in.metadata().evidenceDate(),in.metadata().reviewDueDate(),actor,Instant.now(),prior==null?null:prior.getId());if(prior!=null){prior.supersede();artifacts.saveAndFlush(prior);}row=artifacts.saveAndFlush(row);value.contentChanged();cases.saveAndFlush(value);event(a,value,"EVIDENCE",row.getId(),"ADD_LIVE_SOURCE",actor,null,null,row.getVerificationStatus().name());var out=artifact(row);record(a,"ADD_LIVE_EVIDENCE_SOURCE","EVIDENCE_ARTIFACT",row,null,out,null,c);return out;}
 @Override public ArtifactResponse upload(String a,String id,ArtifactMetadata m,MultipartFile file,String actor,PermissionDataScope scope,String c){var value=caseEntity(a,id);ownerMutation(a,value,actor,scope);check(value.getVersion(),m.caseRecordVersion());var req=requirement(a,value,m.requirementId());byte[] bytes=uploadBytes(file);String media=Objects.requireNonNullElse(file.getContentType(),"");String filename=safeFilename(file.getOriginalFilename());String key=a+"/evidence/"+id+"/"+UUID.randomUUID().toString().replace("-","");String checksum=sha(bytes);EvidenceArtifact prior=superseded(a,value,req,m.supersedesId());storage.put(key,bytes,media);try{var row=artifacts.saveAndFlush(EvidenceArtifact.upload(a,id,req.getId(),req.getCode(),m.title(),m.notes(),filename,storage.provider(),key,media,bytes.length,checksum,m.classification(),m.visibility(),m.retentionTag(),m.evidenceDate(),m.reviewDueDate(),actor,Instant.now(),prior==null?null:prior.getId()));if(prior!=null){prior.supersede();artifacts.saveAndFlush(prior);}value.contentChanged();cases.saveAndFlush(value);event(a,value,"EVIDENCE",row.getId(),"UPLOAD",actor,null,null,row.getVerificationStatus().name());var out=artifact(row);record(a,"UPLOAD_EVIDENCE_ARTIFACT","EVIDENCE_ARTIFACT",row,null,out,null,c);return out;}catch(RuntimeException e){storage.delete(key);throw e;}}
 @Override public ArtifactResponse reverify(String a,String id,String evidenceId,Long version,String token,String actor,PermissionDataScope scope,String c){var value=caseEntity(a,id);access(a,value,actor,scope);check(value.getVersion(),version);var row=artifactEntity(a,id,evidenceId);if(row.getKind()!=EvidenceArtifact.Kind.LIVE_SOURCE)throw new IllegalArgumentException("Only a live source can be reverified");try{var v=sourceVerifier.verify(a,new EvidenceLiveSourceVerifier.Request(row.getSourceType(),row.getSourceId(),row.getSourceVersion(),row.getSourceFingerprint(),row.getSourceChangedAt()),token,actor,c);row.verified("Exact live source remains current",Instant.now());}catch(OptimisticConflictException|ResourceNotFoundException ex){row.failed(ex instanceof OptimisticConflictException?EvidenceArtifact.VerificationStatus.STALE:EvidenceArtifact.VerificationStatus.BROKEN,ex.getMessage(),Instant.now());}row=artifacts.saveAndFlush(row);event(a,value,"EVIDENCE",row.getId(),"REVERIFY",actor,row.getVerificationMessage(),null,row.getVerificationStatus().name());var out=artifact(row);record(a,"REVERIFY_EVIDENCE_SOURCE","EVIDENCE_ARTIFACT",row,null,out,row.getVerificationMessage(),c);return out;}
 @Override@Transactional(readOnly=true)public EvidenceContent download(String a,String id,String evidenceId,String actor,PermissionDataScope scope,String c){var value=caseEntity(a,id);access(a,value,actor,scope);var row=artifactEntity(a,id,evidenceId);if(row.getKind()!=EvidenceArtifact.Kind.UPLOAD)throw new IllegalArgumentException("Evidence is not an uploaded artifact");if(!canSee(row,value,actor,scope))throw new AccessDeniedException("Evidence classification is outside the permitted visibility");record(a,"DOWNLOAD_EVIDENCE_ARTIFACT","EVIDENCE_ARTIFACT",row,null,Map.of("requestedBy",actor),null,c);return new EvidenceContent(row.getOriginalFilename(),row.getMediaType(),row.getByteSize(),storage.get(row.getStorageObjectKey()));}

 @Override public CaseResponse findings(String a,String id,FindingsInput in,String actor,PermissionDataScope scope,String c){var value=caseEntity(a,id);access(a,value,actor,scope);check(value.getVersion(),in.recordVersion());value.reviewable(actor);var reqs=requirements.findByAgencyIdAndFrameworkVersionIdOrderByDisplayOrder(a,value.getFrameworkVersionId());Map<String,EvidenceRequirement>byId=reqs.stream().collect(Collectors.toMap(EvidenceRequirement::getId,Function.identity()));if(in.findings().stream().map(FindingInput::requirementId).distinct().count()!=in.findings().size())throw new IllegalArgumentException("Requirement findings must be unique");Map<String,EvidenceFinding>current=findings.findByAgencyIdAndAssessmentCaseIdAndCurrentRecordTrueOrderByRequirementCode(a,id).stream().collect(Collectors.toMap(EvidenceFinding::getRequirementId,Function.identity()));List<EvidenceFinding>newRows=new ArrayList<>();for(var x:in.findings()){var req=byId.get(x.requirementId());if(req==null)throw new IllegalArgumentException("Finding references a requirement outside the case framework");if(x.outcome()==EvidenceFinding.Outcome.NOT_APPLICABLE&&!req.isAllowsNotApplicable())throw new IllegalArgumentException("Requirement does not allow Not Applicable: "+req.getCode());var prior=current.get(req.getId());if(prior!=null){prior.supersede();findings.save(prior);}int revision=prior==null?1:prior.getFindingRevision()+1;newRows.add(new EvidenceFinding(a,id,req.getId(),req.getCode(),value.getSubmissionRevision(),revision,prior==null?null:prior.getId(),x.outcome(),x.rationale(),x.notApplicableAuthority(),actor,Instant.now()));}findings.saveAllAndFlush(newRows);event(a,value,"CASE",id,"RECORD_FINDINGS",actor,"Human findings recorded",value.getStatus().name(),value.getStatus().name());return auditedCase(a,value,actor,scope,"RECORD_EVIDENCE_FINDINGS","Human findings recorded",c);}
 @Override public CaseResponse returnCase(String a,String id,Transition in,String actor,PermissionDataScope scope,String c){var value=caseEntity(a,id);access(a,value,actor,scope);check(value.getVersion(),in.recordVersion());String from=value.getStatus().name();value.returnForRework(actor,in.reason(),Instant.now());value=cases.saveAndFlush(value);event(a,value,"CASE",id,"RETURN",actor,in.reason(),from,value.getStatus().name());notifications.returned(caseProjection(a,value.getOwnerEmployeeNo(),value),c);return auditedCase(a,value,actor,scope,"RETURN_EVIDENCE_ASSESSMENT_CASE",in.reason(),c);}
 @Override public CaseResponse finalizeCase(String a,String id,Transition in,String actor,PermissionDataScope scope,String c){var value=caseEntity(a,id);access(a,value,actor,scope);check(value.getVersion(),in.recordVersion());value.reviewable(actor);ensureFinalizable(a,value);String from=value.getStatus().name();value.finalizeCase(actor,in.reason(),Instant.now());value=cases.saveAndFlush(value);event(a,value,"CASE",id,"FINALIZE",actor,in.reason(),from,value.getStatus().name());notifications.outcome(caseProjection(a,value.getOwnerEmployeeNo(),value),c);return auditedCase(a,value,actor,scope,"FINALIZE_INTERNAL_EVIDENCE_ASSESSMENT",in.reason(),c);}

 @Override public GapResponse createGap(String a,String id,GapInput in,String actor,PermissionDataScope scope,String c){var value=caseEntity(a,id);access(a,value,actor,scope);check(value.getVersion(),in.recordVersion());value.reviewable(actor);var finding=findings.findByIdAndAgencyIdAndAssessmentCaseId(in.findingId(),a,id).orElseThrow(()->new ResourceNotFoundException("Evidence finding not found"));if(!finding.isCurrentRecord()||!finding.getRequirementId().equals(in.requirementId())||finding.getOutcome()!=EvidenceFinding.Outcome.PARTIALLY_MET&&finding.getOutcome()!=EvidenceFinding.Outcome.NOT_MET)throw new IllegalArgumentException("A gap requires the current Partially Met or Not Met finding");var row=gaps.saveAndFlush(new EvidenceGap(a,id,in.requirementId(),finding.getId(),in.reason(),in.severity(),actor,Instant.now()));event(a,value,"GAP",row.getId(),"OPEN",actor,in.reason(),null,row.getStatus().name());var out=gap(row);record(a,"OPEN_EVIDENCE_GAP","EVIDENCE_GAP",row,null,out,in.reason(),c);return out;}
 @Override public GapResponse updateGap(String a,String id,String gapId,GapUpdate in,String actor,PermissionDataScope scope,String c){var value=caseEntity(a,id);access(a,value,actor,scope);value.reviewable(actor);var row=gapEntity(a,id,gapId);check(row.getVersion(),in.recordVersion());row.update(in.reason(),in.severity());row=gaps.saveAndFlush(row);event(a,value,"GAP",row.getId(),"UPDATE",actor,in.reason(),row.getStatus().name(),row.getStatus().name());return gap(row);}
 @Override public GapResponse transitionGap(String a,String id,String gapId,Transition in,String action,String actor,PermissionDataScope scope,String c){var value=caseEntity(a,id);access(a,value,actor,scope);if(!value.getValidatorEmployeeNo().equalsIgnoreCase(actor)&&scope!=PermissionDataScope.AGENCY_WIDE)throw new AccessDeniedException("Only the assigned validator may decide a gap");var row=gapEntity(a,id,gapId);check(row.getVersion(),in.recordVersion());String from=row.getStatus().name();if("resolve".equals(action)){if(actions.findByAgencyIdAndGapIdOrderByTargetDateAsc(a,gapId).stream().anyMatch(x->x.getStatus()!=EvidenceCorrectiveAction.Status.VERIFIED&&x.getStatus()!=EvidenceCorrectiveAction.Status.CANCELLED))throw new IllegalStateException("All corrective actions must be verified or cancelled before resolving the gap");row.resolve(actor,in.reason(),Instant.now());}else if("reopen".equals(action))row.reopen(actor,in.reason(),Instant.now());else throw new IllegalArgumentException("Unsupported gap action");row=gaps.saveAndFlush(row);event(a,value,"GAP",row.getId(),action.toUpperCase(Locale.ROOT),actor,in.reason(),from,row.getStatus().name());var out=gap(row);record(a,"EVIDENCE_GAP_"+action.toUpperCase(Locale.ROOT),"EVIDENCE_GAP",row,null,out,in.reason(),c);return out;}
 @Override public ActionResponse createAction(String a,String id,ActionInput in,String token,String actor,PermissionDataScope scope,String c){var value=caseEntity(a,id);access(a,value,actor,scope);check(value.getVersion(),in.caseRecordVersion());if(!value.getValidatorEmployeeNo().equalsIgnoreCase(actor)&&scope!=PermissionDataScope.AGENCY_WIDE)throw new AccessDeniedException("Only the validator may create a corrective action");var gap=gapEntity(a,id,in.gapId());if(gap.getStatus()==EvidenceGap.Status.RESOLVED)throw new IllegalStateException("Resolved gap cannot receive another corrective action");var responsible=person(in.responsibleEmployeeNo(),token);var row=actions.saveAndFlush(new EvidenceCorrectiveAction(a,gap.getId(),id,in.actionPlan(),responsible.employeeNo(),responsible.name(),in.targetDate()));event(a,value,"ACTION",row.getId(),"CREATE",actor,null,null,row.getStatus().name());var out=action(row);record(a,"CREATE_EVIDENCE_CORRECTIVE_ACTION","EVIDENCE_CORRECTIVE_ACTION",row,null,out,null,c);notifications.assign(actionProjection(a,row.getResponsibleEmployeeNo(),row),c);return out;}
 @Override public ActionResponse updateAction(String a,String id,String actionId,ActionUpdate in,String actor,PermissionDataScope scope,String c){var value=caseEntity(a,id);access(a,value,actor,scope);var row=actionEntity(a,id,actionId);check(row.getVersion(),in.recordVersion());if(!row.getResponsibleEmployeeNo().equalsIgnoreCase(actor)&&scope!=PermissionDataScope.AGENCY_WIDE)throw new AccessDeniedException("Only the responsible employee may update the corrective action");row.update(in.actionPlan(),in.targetDate(),in.progressNote());row=actions.saveAndFlush(row);event(a,value,"ACTION",row.getId(),"UPDATE",actor,in.progressNote(),row.getStatus().name(),row.getStatus().name());return action(row);}
 @Override public ActionResponse submitAction(String a,String id,String actionId,ActionSubmit in,String actor,PermissionDataScope scope,String c){var value=caseEntity(a,id);access(a,value,actor,scope);var row=actionEntity(a,id,actionId);check(row.getVersion(),in.recordVersion());String from=row.getStatus().name();row.submit(actor,in.progressNote(),in.completionEvidenceReference(),Instant.now());row=actions.saveAndFlush(row);event(a,value,"ACTION",row.getId(),"SUBMIT",actor,in.progressNote(),from,row.getStatus().name());notifications.replaceAssignment(actionProjection(a,value.getValidatorEmployeeNo(),row),c);return action(row);}
 @Override public ActionResponse transitionAction(String a,String id,String actionId,Transition in,String transition,String actor,PermissionDataScope scope,String c){var value=caseEntity(a,id);access(a,value,actor,scope);var row=actionEntity(a,id,actionId);check(row.getVersion(),in.recordVersion());String from=row.getStatus().name();if("start".equals(transition))row.start(actor,in.reason());else{if(!value.getValidatorEmployeeNo().equalsIgnoreCase(actor)&&scope!=PermissionDataScope.AGENCY_WIDE)throw new AccessDeniedException("Only the assigned validator may decide the corrective action");if(row.getResponsibleEmployeeNo().equalsIgnoreCase(actor))throw new AccessDeniedException("The responsible employee cannot verify the same action");if("verify".equals(transition))row.verify(actor,in.reason(),Instant.now());else if("return".equals(transition))row.returnForRework(actor,in.reason());else if("cancel".equals(transition))row.cancel(actor,in.reason());else throw new IllegalArgumentException("Unsupported corrective action transition");}row=actions.saveAndFlush(row);event(a,value,"ACTION",row.getId(),transition.toUpperCase(Locale.ROOT),actor,in.reason(),from,row.getStatus().name());var out=action(row);record(a,"EVIDENCE_ACTION_"+transition.toUpperCase(Locale.ROOT),"EVIDENCE_CORRECTIVE_ACTION",row,null,out,in.reason(),c);if("return".equals(transition))notifications.returned(actionProjection(a,row.getResponsibleEmployeeNo(),row),c);else if("verify".equals(transition)||"cancel".equals(transition))notifications.outcome(actionProjection(a,row.getResponsibleEmployeeNo(),row),c);return out;}

 private void ensureCurrentEvidenceHealthy(String a,EvidenceAssessmentCase c){var current=artifacts.findByAgencyIdAndAssessmentCaseIdAndCurrentRecordTrueOrderByAddedAtAsc(a,c.getId());if(current.stream().anyMatch(x->x.getVerificationStatus()!=EvidenceArtifact.VerificationStatus.VERIFIED))throw new IllegalStateException("Current evidence contains a stale, broken, or unverified source");}
 private void ensureFinalizable(String a,EvidenceAssessmentCase c){List<EvidenceRequirement> req=requirements.findByAgencyIdAndFrameworkVersionIdOrderByDisplayOrder(a,c.getFrameworkVersionId());Map<String,EvidenceFinding> f=findings.findByAgencyIdAndAssessmentCaseIdAndCurrentRecordTrueOrderByRequirementCode(a,c.getId()).stream().collect(Collectors.toMap(EvidenceFinding::getRequirementId,Function.identity()));if(f.size()!=req.size()||req.stream().anyMatch(x->!f.containsKey(x.getId())))throw new IllegalStateException("Every framework requirement requires a current human finding");if(f.values().stream().anyMatch(x->x.getOutcome()==EvidenceFinding.Outcome.NEEDS_REVIEW))throw new IllegalStateException("Needs Review findings must be resolved before finalization");var evidence=artifacts.findByAgencyIdAndAssessmentCaseIdAndCurrentRecordTrueOrderByAddedAtAsc(a,c.getId());for(var r:req){var finding=f.get(r.getId());if(finding.getOutcome()==EvidenceFinding.Outcome.MET||finding.getOutcome()==EvidenceFinding.Outcome.PARTIALLY_MET){boolean supported=evidence.stream().anyMatch(x->x.getRequirementId().equals(r.getId())&&x.getVerificationStatus()==EvidenceArtifact.VerificationStatus.VERIFIED&&(x.getReviewDueDate()==null||!x.getReviewDueDate().isBefore(LocalDate.now(MANILA))));if(!supported)throw new IllegalStateException("Met or Partially Met finding lacks current verified evidence: "+r.getCode());}if((finding.getOutcome()==EvidenceFinding.Outcome.PARTIALLY_MET||finding.getOutcome()==EvidenceFinding.Outcome.NOT_MET)&&gaps.findByAgencyIdAndAssessmentCaseIdOrderByOpenedAtAsc(a,c.getId()).stream().noneMatch(x->x.getFindingId().equals(finding.getId())))throw new IllegalStateException("Partially Met or Not Met finding requires a reasoned gap: "+r.getCode());}}
 private EvidenceArtifact superseded(String a,EvidenceAssessmentCase c,EvidenceRequirement req,String id){if(id==null||id.isBlank())return null;var prior=artifactEntity(a,c.getId(),id);if(!prior.isCurrentRecord()||!prior.getRequirementId().equals(req.getId()))throw new IllegalArgumentException("Replacement must supersede current evidence for the same requirement");return prior;}
 private EvidenceAssessmentCase.Person person(String employeeNo,String token){var d=directory.require(employeeNo,token);var s=hr.get(d.employeeId(),token);if(!s.employeeNo().equalsIgnoreCase(employeeNo)||s.appointmentId()==null||s.sourceFingerprint()==null)throw new OptimisticConflictException("Employee appointment source is incomplete or changed");return new EvidenceAssessmentCase.Person(s.employeeId(),s.employeeNo(),s.displayName(),s.appointmentId(),s.sourceFingerprint());}
 private AdministrativePerformancePlanningClient.OrganizationTarget organization(String type,Long id,String token){String t=Objects.requireNonNullElse(type,"").trim().toUpperCase(Locale.ROOT);if(!Set.of("AREA","BUSINESS_UNIT").contains(t))throw new IllegalArgumentException("organizationType must be AREA or BUSINESS_UNIT");var o=administrative.organization(t,id,token);if(!t.equals(o.type())||!id.equals(o.id())||o.sourceFingerprint()==null)throw new OptimisticConflictException("Organization source is incomplete or changed");return o;}
 private boolean visible(String a,EvidenceAssessmentCase c,String actor,PermissionDataScope scope){if(scope==PermissionDataScope.AGENCY_WIDE)return true;if(c.getOwnerEmployeeNo().equalsIgnoreCase(actor)||c.getValidatorEmployeeNo().equalsIgnoreCase(actor))return true;return actions.findByAgencyIdAndAssessmentCaseIdOrderByTargetDateAsc(a,c.getId()).stream().anyMatch(x->x.getResponsibleEmployeeNo().equalsIgnoreCase(actor));}private void access(String a,EvidenceAssessmentCase c,String actor,PermissionDataScope scope){if(!visible(a,c,actor,scope))throw new AccessDeniedException("Assessment case is outside the permitted assignment scope");}private void ownerMutation(String a,EvidenceAssessmentCase c,String actor,PermissionDataScope scope){access(a,c,actor,scope);if(scope!=PermissionDataScope.AGENCY_WIDE&&!c.getOwnerEmployeeNo().equalsIgnoreCase(actor))throw new AccessDeniedException("Only the assigned evidence owner may change case evidence");c.editable();}
 private boolean canSee(EvidenceArtifact e,EvidenceAssessmentCase c,String actor,PermissionDataScope scope){if(scope==PermissionDataScope.AGENCY_WIDE)return true;if(e.getVisibility()==EvidenceArtifact.Visibility.AGENCY_AUTHORIZED)return false;if(e.getVisibility()==EvidenceArtifact.Visibility.VALIDATOR_ONLY)return c.getValidatorEmployeeNo().equalsIgnoreCase(actor);return c.getOwnerEmployeeNo().equalsIgnoreCase(actor)||c.getValidatorEmployeeNo().equalsIgnoreCase(actor);}
 private byte[] uploadBytes(MultipartFile file){if(!properties.storage().enabled())throw new IllegalStateException("Document uploads are disabled");if(file==null||file.isEmpty()||file.getSize()>properties.storage().maximumBytes())throw new IllegalArgumentException("Evidence size is invalid");String media=Objects.requireNonNullElse(file.getContentType(),"");if(!properties.storage().allowedMediaTypes().contains(media))throw new IllegalArgumentException("Evidence media type is not allowed");try{byte[] bytes=file.getBytes();verifySignature(media,bytes);return bytes;}catch(IOException e){throw new IllegalArgumentException("Evidence could not be read",e);}}
 private static void verifySignature(String media,byte[] b){boolean ok=switch(media){case"application/pdf"->b.length>=5&&b[0]=='%'&&b[1]=='P'&&b[2]=='D'&&b[3]=='F'&&b[4]=='-';case"image/png"->b.length>=8&&(b[0]&255)==137&&b[1]=='P'&&b[2]=='N'&&b[3]=='G';case"image/jpeg"->b.length>=3&&(b[0]&255)==255&&(b[1]&255)==216&&(b[2]&255)==255;default->false;};if(!ok)throw new IllegalArgumentException("Evidence content does not match its declared media type");}private static String safeFilename(String value){String name=Objects.requireNonNullElse(value,"evidence").replace('\\','/');name=name.substring(name.lastIndexOf('/')+1).replaceAll("[^A-Za-z0-9._ -]","_").trim();return name.isBlank()?"evidence":name.substring(0,Math.min(255,name.length()));}
 private CycleResponse cycleResponse(EvidenceAssessmentCycle x){return new CycleResponse(x.getId(),x.getVersion(),x.getCode(),x.getTitle(),x.getDescription(),x.getFrameworkVersionId(),x.getFrameworkDefinitionVersion(),x.getFrameworkContentRevision(),x.getFrameworkFingerprint(),x.getPeriodStart(),x.getPeriodEnd(),x.getDueDate(),x.getStatus().name(),x.getOpenedBy(),x.getOpenedAt(),x.getClosedBy(),x.getClosedAt(),x.getTransitionReason());}
 private CaseResponse caseResponse(String a,EvidenceAssessmentCase x,String actor,PermissionDataScope scope){var evidence=artifacts.findByAgencyIdAndAssessmentCaseIdOrderByAddedAtAsc(a,x.getId()).stream().filter(e->canSee(e,x,actor,scope)).map(this::artifact).toList();return new CaseResponse(x.getId(),x.getVersion(),x.getContentRevision(),x.getCycleId(),x.getFrameworkVersionId(),x.getCode(),x.getTitle(),x.getOrganizationType(),x.getOrganizationId(),x.getOrganizationName(),x.getOrganizationFingerprint(),x.getOwnerEmployeeId(),x.getOwnerEmployeeNo(),x.getOwnerName(),x.getOwnerAppointmentId(),x.getOwnerFingerprint(),x.getValidatorEmployeeId(),x.getValidatorEmployeeNo(),x.getValidatorName(),x.getValidatorAppointmentId(),x.getValidatorFingerprint(),x.isValidatorRecused(),x.getRecusalReason(),x.getStatus().name(),x.getSubmissionRevision(),x.getSubmittedBy(),x.getSubmittedAt(),x.getReturnedBy(),x.getReturnedAt(),x.getReturnReason(),x.getFinalizedBy(),x.getFinalizedAt(),x.getFinalizationReason(),x.getWithdrawnBy(),x.getWithdrawnAt(),x.getWithdrawalReason(),evidence,findings.findByAgencyIdAndAssessmentCaseIdOrderByDecidedAtAsc(a,x.getId()).stream().map(this::finding).toList(),gaps.findByAgencyIdAndAssessmentCaseIdOrderByOpenedAtAsc(a,x.getId()).stream().map(this::gap).toList(),actions.findByAgencyIdAndAssessmentCaseIdOrderByTargetDateAsc(a,x.getId()).stream().map(this::action).toList(),events.findByAgencyIdAndAssessmentCaseIdOrderByEventAtAsc(a,x.getId()).stream().map(this::eventResponse).toList());}
 private ArtifactResponse artifact(EvidenceArtifact x){return new ArtifactResponse(x.getId(),x.getVersion(),x.getRequirementId(),x.getRequirementCode(),x.getTitle(),x.getNotes(),x.getKind().name(),x.getSourceType()==null?null:x.getSourceType().name(),x.getSourceId(),x.getSourceVersion(),x.getSourceFingerprint(),x.getSourceLabel(),x.getSourceChangedAt(),x.getOriginalFilename(),x.getMediaType(),x.getByteSize(),x.getChecksum(),x.getClassification().name(),x.getVisibility().name(),x.getRetentionTag(),x.getEvidenceDate(),x.getReviewDueDate(),x.getLastVerifiedAt(),x.getVerificationStatus().name(),x.getVerificationMessage(),x.getSupersedesId(),x.isCurrentRecord(),x.getAddedBy(),x.getAddedAt());}private FindingResponse finding(EvidenceFinding x){return new FindingResponse(x.getId(),x.getVersion(),x.getRequirementId(),x.getRequirementCode(),x.getSubmissionRevision(),x.getFindingRevision(),x.getSupersedesId(),x.isCurrentRecord(),x.getOutcome().name(),x.getRationale(),x.getNotApplicableAuthority(),x.getDecidedBy(),x.getDecidedAt());}private GapResponse gap(EvidenceGap x){return new GapResponse(x.getId(),x.getVersion(),x.getRequirementId(),x.getFindingId(),x.getReason(),x.getSeverity(),x.getStatus().name(),x.getOpenedBy(),x.getOpenedAt(),x.getResolvedBy(),x.getResolvedAt(),x.getResolutionReason());}private ActionResponse action(EvidenceCorrectiveAction x){return new ActionResponse(x.getId(),x.getVersion(),x.getGapId(),x.getActionPlan(),x.getResponsibleEmployeeNo(),x.getResponsibleName(),x.getTargetDate(),x.getStatus().name(),x.getProgressNote(),x.getCompletionEvidenceReference(),x.getSubmittedBy(),x.getSubmittedAt(),x.getVerifiedBy(),x.getVerifiedAt(),x.getDecisionReason());}private EventResponse eventResponse(EvidenceAssessmentEvent x){return new EventResponse(x.getId(),x.getAggregateType(),x.getAggregateId(),x.getEventType(),x.getActorEmployeeNo(),x.getReason(),x.getFromStatus(),x.getToStatus(),x.getEventAt());}
 private static NotificationProjectionService.Projection caseProjection(String a,String recipient,EvidenceAssessmentCase value){return new NotificationProjectionService.Projection(a,recipient,SourceDomain.EVIDENCE,"EVIDENCE_ASSESSMENT_CASE",value.getId(),value.getVersion(),null);}private static NotificationProjectionService.Projection actionProjection(String a,String recipient,EvidenceCorrectiveAction value){return new NotificationProjectionService.Projection(a,recipient,SourceDomain.EVIDENCE,"EVIDENCE_CORRECTIVE_ACTION",value.getId(),value.getVersion(),value.getTargetDate().atTime(23,59,59).atZone(MANILA).toInstant());}
 private void event(String a,EvidenceAssessmentCase c,String aggregate,String id,String type,String actor,String reason,String from,String to){events.save(new EvidenceAssessmentEvent(a,c.getId(),aggregate,id,type,actor,reason,from,to,Instant.now()));}private CaseResponse auditedCase(String a,EvidenceAssessmentCase value,String actor,PermissionDataScope scope,String action,String reason,String c){var out=caseResponse(a,value,actor,scope);record(a,action,"EVIDENCE_ASSESSMENT_CASE",value,null,out,reason,c);return out;}private void record(String a,String action,String type,com.primehr.rsp.domain.RspAuditedEntity value,Object before,Object after,String reason,String correlation){audit.record(a,action,type,value.getId(),null,value.getVersion(),before,after,reason,correlation);}
 private EvidenceAssessmentCycle cycleEntity(String a,String id){return cycles.findByIdAndAgencyId(id,a).orElseThrow(()->new ResourceNotFoundException("Evidence assessment cycle not found"));}private EvidenceAssessmentCase caseEntity(String a,String id){return cases.findByIdAndAgencyId(id,a).orElseThrow(()->new ResourceNotFoundException("Evidence assessment case not found"));}private EvidenceArtifact artifactEntity(String a,String c,String id){return artifacts.findByIdAndAgencyIdAndAssessmentCaseId(id,a,c).orElseThrow(()->new ResourceNotFoundException("Evidence artifact not found"));}private EvidenceGap gapEntity(String a,String c,String id){return gaps.findByIdAndAgencyIdAndAssessmentCaseId(id,a,c).orElseThrow(()->new ResourceNotFoundException("Evidence gap not found"));}private EvidenceCorrectiveAction actionEntity(String a,String c,String id){return actions.findByIdAndAgencyIdAndAssessmentCaseId(id,a,c).orElseThrow(()->new ResourceNotFoundException("Evidence corrective action not found"));}private EvidenceRequirement requirement(String a,EvidenceAssessmentCase c,String id){return requirements.findByIdAndAgencyIdAndFrameworkVersionId(id,a,c.getFrameworkVersionId()).orElseThrow(()->new ResourceNotFoundException("Evidence requirement not found in the case framework"));}
 private static void published(FrameworkResponse fw){if(!"PUBLISHED".equals(fw.status()))throw new IllegalStateException("Assessment cycle requires an exact published framework version");}private static void check(long actual,Long expected){if(expected==null||actual!=expected)throw new OptimisticConflictException("Record changed; reload and retry");}private static String norm(String x){return Objects.requireNonNullElse(x,"").trim().toUpperCase(Locale.ROOT);}private String shaObject(Object x){try{return sha(json.writeValueAsString(x).getBytes(StandardCharsets.UTF_8));}catch(Exception e){throw new IllegalStateException("Fingerprint could not be calculated",e);}}private static String sha(byte[] b){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(b));}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}}
}
